-- Which program tile a pane shows in the tab bar. Generated by
-- scripts/build-program-icons from reference/gorex (github.com/egoist/gorex).
-- A tile is NAME.png in config/rex/program-icons; NAME-back1/2.png sit behind.
local M={}
local tiles={
  ["agent"]="agent",
  ["ai"]="agent",
  ["aider"]="agent",
  ["amp"]="agent",
  ["btop"]="btop",
  ["bun"]="bun",
