}
local shells={zsh=true,bash=true,fish=true,sh=true,dash=true,nu=true,pwsh=true,elvish=true,xonsh=true,tcsh=true,csh=true,ksh=true}
local palette=8

-- FNV-1a, as gorex picks the colour of a program without a tile.
local function hash(text)
  local h=2166136261
  for i=1,#text do h=((h ~ text:byte(i))*16777619) & 0xffffffff end
  return h
end

-- Returns a resolver, or nil when the tile directory is missing.
function M.load(wezterm,dir)
  local ok,files=pcall(wezterm.read_dir,dir)
  if not ok or type(files)~='table' then return nil end
  local have={}
  for _,path in ipairs(files) do
    local name=path:match('([^/\\]+)%.png$')
    if name then have[name]=true end
  end
  if not have.shell then return nil end
  local resolver={}
  -- The tile for a process: its own, a shell's, or a coloured one.
  function resolver.slug(name)
    if type(name)~='string' or name=='' then return 'shell' end
    name=(name:match('([^/\\]+)$') or name):gsub('^%-+','')
    local lower=name:lower()
    local found=tiles[lower] or tiles[(lower:gsub('[%d%.%-]+$',''))]
    if found and have[found] then return found end
    if shells[name] then return 'shell' end
    local other='other-'..(hash(name)%palette)
    return have[other] and other or 'shell'
  end
  -- The text that draws a stack in the tab bar: the focused pane's tile in
  -- front, up to two others behind it. It takes `cells` cells. With
  -- `button`, the tiles sit on a rounded button.
  function resolver.cells(slugs,cells,button)
    return '\27]7778;icon;'..table.concat(slugs,',',1,math.min(#slugs,3))..';'..tostring(cells)..(button and ';button' or '')..'\7'
  end
  function resolver.width(count) return count>=3 and 4 or 3 end
  return resolver
end
return M
